import nltk
from nltk.stem import WordNetLemmatizer
from nltk import pos_tag, word_tokenize
import string

nltk.download('averaged_perceptron_tagger')
nltk.download('punkt')
nltk.download('wordnet')


class Lemmatization:
    PUNCTUATION_TABLE = str.maketrans('', '', string.punctuation)

    def __init__(self):
        self._lemmatizer = WordNetLemmatizer()

    @property
    def lemmatizer(self):
        return self._lemmatizer

    @lemmatizer.setter
    def lemmatizer(self, value):
        self._lemmatizer = value

    def lemmatize_sentence(self, sentence):
        clean_sentence = self.remove_punctuation(sentence)
        words = word_tokenize(clean_sentence)
        tagged_words = pos_tag(words)
        return [self.lemmatize_word(word, tag) for word, tag in tagged_words]

    def lemmatize_word(self, word, tag):
        if tag.startswith('V'):
            return self.lemmatizer.lemmatize(word, pos='v')
        elif tag.startswith('J'):
            return self.lemmatizer.lemmatize(word, pos='a')
        elif tag.startswith('R'):
            return self.lemmatizer.lemmatize(word, pos='r')
        else:
            return self.lemmatizer.lemmatize(word)

    def get_pos_tag(self, sentence):
        clean_sentence = self.remove_punctuation(sentence)
        words = word_tokenize(clean_sentence)
        tagged_words = pos_tag(words)
        return [tag for _, tag in tagged_words]

    def remove_punctuation(self, sentence):
        return sentence.translate(self.PUNCTUATION_TABLE)
